text:
{
  "hypotheses": [
    {
      "id": "h1",
      "kind": "feature_code",
      "rationale": "energy_star_rating и floor_area — два самых важных числовых признака; их явное взаимодействие может помочь модели учесть, что влияние рейтинга на удельное потребление зависит от масштаба здания.",
      "patch": {
        "features.custom": [
          "+fe_star_area_log"
        ]
      },
      "feature_spec": "fe_star_area_log = energy_star_rating * log1p(floor_area); если energy_star_rating NaN, результат NaN",
      "expected": "RMSE снизится за счет более точной оценки для крупных и малых зданий с разным энергоэффективным рейтингом.",
      "cost": "low"
    },
    {
      "id": "h2",
      "kind": "config",
      "rationale": "year_built имеет высокую важность, но не входит в group_stats; агрегаты внутри facility_type могут стабилизировать влияние возраста и учесть типичный возраст зданий каждого типа.",
      "patch": {
        "features.group_cols": [
          "+year_built"
        ]
      },
      "feature_spec": null,
      "expected": "RMSE снизится за счет более стабильных признаков возраста по типам зданий.",
      "cost": "low"
    },
    {
      "id": "h3",
      "kind": "model",
      "rationale": "Текущий XGBoost может быть ограничен max_depth=7 и min_child_weight=5; увеличение глубины до 8 с меньшей min_child_weight и умеренной регуляризацией может лучше улавливать взаимодействия, а subsample/colsample 0.7 снизит переобучение.",
      "patch": {
        "model.params.max_depth": 8,
        "model.params.min_child_weight": 3,
        "model.params.reg_lambda": 2,
        "model.params.subsample": 0.7,
        "model.params.colsample_bytree": 0.7
      },
      "feature_spec": null,
      "expected": "RMSE снизится за счет более гибкой, но регуляризованной модели.",
      "cost": "medium"
    },
    {
      "id": "h4",
      "kind": "feature_code",
      "rationale": "fe_total_dd уже есть, но разность HDD и CDD показывает доминирование отопления или охлаждения, что может быть важнее для энергопотребления, чем их сумма; ratio неудачен из-за чувствительности к малым CDD.",
      "patch": {
        "features.custom": [
          "+fe_hdd_cdd_diff"
        ]
      },
      "feature_spec": "fe_hdd_cdd_diff = heating_degree_days_c - cooling_degree_days_c",
      "expected": "RMSE снизится за счет лучшего разделения климатических режимов.",
      "cost": "low"
    },
    {
      "id": "h5",
      "kind": "model",
      "rationale": "LightGBM может иначе обрабатывать пропуски и взаимодействия, особенно с текущими признаками; разнообразие моделей полезно для финального бленда.",
      "patch": {
        "model.name": "lightgbm",
        "model.params": {
          "learning_rate": 0.05,
          "num_leaves": 63,
          "min_child_samples": 50,
          "subsample": 0.8,
          "colsample_bytree": 0.8,
          "reg_lambda": 5
        }
      },
      "feature_spec": null,
      "expected": "RMSE может снизиться или дать альтернативную модель для бленда.",
      "cost": "medium"
    }
  ]
}
